// 세션정보를 얻기위한 함수사용

scwin.clickBzProcsNo = "";
scwin.clickIsurCd = "";
scwin.clickComNm = "";
scwin.vScrenID = "ULDSTF60007.xml";
scwin.fn_GetPar;
scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_setCode = function() {
    //var usrCBData ="전체^(null),일반^1,벤처^2,기술정상^3,대형^4,스팩^5,스팩합병^6,분할재상장^7,외국기업^8"; 
    //cmb_INVSTG_CD.CBData =  usrCBData; 

    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    $c.stf.setObjectValue(edt_BILL_STRT_DD, $c.ut.cGetMinusDate2(vCurDate, 365)); // 일년 날짜
    $c.stf.setObjectValue(edt_BILL_END_DD, $c.ut.cGetToday("yyyymmdd")); // 현재날짜
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp1);
    $c.stf.setObjectValue(edt_COMITE_STRT_DD, $c.ut.cGetMinusDate2(vCurDate, 365)); // 일년 날짜
    $c.stf.setObjectValue(edt_COMITE_END_DD, $c.ut.cGetToday("yyyymmdd")); // 현재날짜
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp2);
};
scwin.fn_setBzProcsNo = function(obj) {
    scwin.clickIsurCd = dts_List.getCellData(eval(obj), "ISUR_CD");
    scwin.clickComNm = dts_List.getCellData(eval(obj), "COM_NM");
    scwin.clickBzProcsNo = dts_List.getCellData(eval(obj), "BZ_PROCS_NO");
};
scwin.fn_getBzProcsNo = function() {
    return scwin.clickBzProcsNo;
};
scwin.fn_list_sync = function() {
    var V_SECUGPR_ID = "";
    var V_LIST_TP_CLSS = "";
    var V_LIST_CLSS = "";
    var V_RSLT = " ";

    //기업구분
    var previousChecked = false;
    V_SECUGPR_ID = " AND SECUGRP_ID IN ( ";
    if (chk_SECUGRP1.checked) {
        if (previousChecked) {
            V_SECUGPR_ID += ",  'ST' ";
        } else {
            V_SECUGPR_ID += " 'ST' ";
        }
        previousChecked = true;
    }
    if (chk_SECUGRP2.checked) {
        if (previousChecked) {
            V_SECUGPR_ID += ",  'FS' ";
        } else {
            V_SECUGPR_ID += " 'FS' ";
        }
        previousChecked = true;
    }
    if (chk_SECUGRP3.checked) {
        if (previousChecked) {
            V_SECUGPR_ID += ",  'DR' ";
        } else {
            V_SECUGPR_ID += " 'DR' ";
        }
        previousChecked = true;
    }
    if (chk_SECUGRP4.checked) {
        if (previousChecked) {
            V_SECUGPR_ID += ",  'RT' ";
        } else {
            V_SECUGPR_ID += " 'RT' ";
        }
        previousChecked = true;
    }
    if (previousChecked) {
        V_SECUGPR_ID += " ) ";
    } else {
        V_SECUGPR_ID = "";
    }

    /*상장구분*/
    var previousChecked = false;
    V_LIST_TP_CLSS = " AND LIST_TP_CLSS_CD IN ( ";
    if (chk_LIST_TP_CLSS1.checked) {
        if (previousChecked) {
            V_LIST_TP_CLSS += ",  '00' ";
        } else {
            V_LIST_TP_CLSS += " '00' ";
        }
        previousChecked = true;
    }
    if (chk_LIST_TP_CLSS2.checked) {
        if (previousChecked) {
            V_LIST_TP_CLSS += ",  '01' ";
        } else {
            V_LIST_TP_CLSS += " '01' ";
        }
        previousChecked = true;
    }
    if (chk_LIST_TP_CLSS3.checked) {
        if (previousChecked) {
            V_LIST_TP_CLSS += ",  '02' ";
        } else {
            V_LIST_TP_CLSS += " '02' ";
        }
        previousChecked = true;
    }
    if (chk_LIST_TP_CLSS4.checked) {
        if (previousChecked) {
            V_LIST_TP_CLSS += ",  '03' ";
        } else {
            V_LIST_TP_CLSS += " '03' ";
        }
        previousChecked = true;
    }
    /*if( chk_LIST_TP_CLSS5.checked){
    	if(previousChecked){
    			V_LIST_TP_CLSS  +=  ",  '04' ";
    	} else {
    			V_LIST_TP_CLSS  +=   " '04' ";
    	}
    	previousChecked = true;
    }*/
    if (chk_LIST_TP_CLSS6.checked) {
        if (previousChecked) {
            V_LIST_TP_CLSS += ",  '05' ";
        } else {
            V_LIST_TP_CLSS += " '05' ";
        }
        previousChecked = true;
    }
    if (chk_LIST_TP_CLSS7.checked) {
        if (previousChecked) {
            V_LIST_TP_CLSS += ",  '06' ";
        } else {
            V_LIST_TP_CLSS += " 06' ";
        }
        previousChecked = true;
    }
    if (previousChecked) {
        V_LIST_TP_CLSS += " ) ";
    } else {
        V_LIST_TP_CLSS = "";
    }

    /*상장유형*/
    var previousChecked = false;
    V_LIST_CLSS = " AND LIST_CLSS_CD IN ( ";
    if (chk_LIST_CLSS1.checked) {
        if (previousChecked) {
            V_LIST_CLSS += ",  '10' ";
        } else {
            V_LIST_CLSS += " '10' ";
        }
        previousChecked = true;
    }
    if (chk_LIST_CLSS2.checked) {
        if (previousChecked) {
            V_LIST_CLSS += ",  '20' ";
        } else {
            V_LIST_CLSS += " '20' ";
        }
        previousChecked = true;
    }
    if (chk_LIST_CLSS3.checked) {
        if (previousChecked) {
            V_LIST_CLSS += ",  '21' ";
        } else {
            V_LIST_CLSS += " '21' ";
        }
        previousChecked = true;
    }
    if (chk_LIST_CLSS4.checked) {
        if (previousChecked) {
            V_LIST_CLSS += ",  '22' ";
        } else {
            V_LIST_CLSS += " '22' ";
        }
        previousChecked = true;
    }
    if (chk_LIST_CLSS5.checked) {
        if (previousChecked) {
            V_LIST_CLSS += ",  '23' ";
        } else {
            V_LIST_CLSS += " '23' ";
        }
        previousChecked = true;
    }
    if (chk_LIST_CLSS6.checked) {
        if (previousChecked) {
            V_LIST_CLSS += ",  '24' ";
        } else {
            V_LIST_CLSS += " '24 ";
        }
        previousChecked = true;
    }
    if (previousChecked) {
        V_LIST_CLSS += " ) ";
    } else {
        V_LIST_CLSS = "";
    }

    /*심사결과*/
    previousChecked = false;
    V_RSLT = " AND COMITE_INVSTG_RSLT_CD IN ( ";
    if (chk_COMITE_RSLT1.checked) {
        V_RSLT += " '1' ";
        previousChecked = true;
    }
    if (chk_COMITE_RSLT2.checked) {
        if (previousChecked) {
            V_RSLT += ", '2' ";
        } else {
            V_RSLT += " '2' ";
        }
        previousChecked = true;
    }
    if (chk_COMITE_RSLT3.checked) {
        if (previousChecked) {
            V_RSLT += ", '3' ";
        } else {
            V_RSLT += " '3' ";
        }
        previousChecked = true;
    }
    if (chk_COMITE_RSLT4.checked) {
        if (previousChecked) {
            V_RSLT += ", '4' ";
        } else {
            V_RSLT += " '4' ";
        }
        previousChecked = true;
    }
    if (previousChecked) {
        V_RSLT += " ) ";
    } else {
        V_RSLT = "";
    }
    var stdIndCd = $c.stf.getObjectValue(txb_STD_IND_CD) == '' ? "A" : $c.stf.getObjectValue(txb_STD_IND_CD);

    /*if(getObjectValue(tbx_STD_IND_CD) != ''){
			stdIndCd = ;
	   }*/

    /*
        var	url = "/listingCommon.do?method=listGeneralForDynamicName&outputMessageId=COMITERSLT_INOUT" +
					 "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + 
					 "&queryId=lds.stf.lstinvstg.prelminvstg.kospi.comitedelib.select.list"+ 
					 "&{P}COM_NM=" +  getObjectValue(tbx_COM_NM) + 
					 "&{P}COMITE_STRT_DD=" + getObjectValue(edt_COMITE_STRT_DD)+ 
					 "&{P}COMITE_END_DD=" +  getObjectValue(edt_COMITE_END_DD)+ 
					 "&{P}BILL_STRT_DD=" +  getObjectValue(edt_BILL_STRT_DD)+ 
					 "&{P}BILL_END_DD=" +  getObjectValue(edt_BILL_END_DD)+ 
					 "&{P}MAJ_PROD_NM=" + getObjectValue( tbx_MAJ_PROD_NM) + 
					 "&{P}EMP_NM=" + getObjectValue( tbx_EMP_NM) + 
					 "&{P}STD_IND_CD=" + stdIndCd+ 
					 "&{P}V_RSLT=" + V_RSLT +
					 "&{P}V_SECUGPR_ID=" + V_SECUGPR_ID +
					 "&{P}V_LIST_TP_CLSS=" + V_LIST_TP_CLSS +
					 "&{P}V_LIST_CLSS=" + V_LIST_CLSS +
					 "&{P}V_ISUE_CONTN=" + getObjectValue( tbx_isue_contn_search) + 
					 "&{P}V_EMPH_INVSTG=" + getObjectValue( tbx_emph_invstg_search) + 
					 "&{P}V_NAPPROV_RSN=" + getObjectValue( tbx_napprov_rsn_search) ;

		dts_List.DataID = encodeURI(url);
		dts_List.Reset();*/


    var url = "/ComiteDelib.do?method=searchPrelistComitDelibRslt&outputMessageId=COMITERSLT_INOUT&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&SCREN_ID=" + scwin.vScrenID + "&queryId=lds.stf.lstinvstg.prelminvstg.kospi.comitedelib.select.list" + "&{P}COM_NM=" + $c.stf.getObjectValue(tbx_COM_NM) + "&{P}COMITE_STRT_DD=" + $c.stf.getObjectValue(edt_COMITE_STRT_DD) + "&{P}COMITE_END_DD=" + $c.stf.getObjectValue(edt_COMITE_END_DD) + "&{P}BILL_STRT_DD=" + $c.stf.getObjectValue(edt_BILL_STRT_DD) + "&{P}BILL_END_DD=" + $c.stf.getObjectValue(edt_BILL_END_DD) + "&{P}MAJ_PROD_NM=" + $c.stf.getObjectValue(tbx_MAJ_PROD_NM) + "&{P}EMP_NM=" + $c.stf.getObjectValue(tbx_EMP_NM) + "&{P}STD_IND_CD=" + stdIndCd + "&{P}V_RSLT=" + V_RSLT + "&{P}V_SECUGPR_ID=" + V_SECUGPR_ID + "&{P}V_LIST_TP_CLSS=" + V_LIST_TP_CLSS + "&{P}V_LIST_CLSS=" + V_LIST_CLSS + "&{P}V_ISUE_CONTN=" + $c.stf.getObjectValue(tbx_isue_contn_search) + "&{P}V_EMPH_INVSTG=" + $c.stf.getObjectValue(tbx_emph_invstg_search) + "&{P}V_NAPPROV_RSN=" + $c.stf.getObjectValue(tbx_napprov_rsn_search);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};


/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (dts_List.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, "리스트", "", "3");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
scwin.fn_GetParStdInd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_STD_IND_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_STD_IND_NM); // 명칭값을 포함할 컨트롤

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParStdInd = function(arrPar) {
    txb_STD_IND_CD.setValue(arrPar[0].STD_IND_CD);
    txb_STD_IND_NM.setValue(arrPar[0].IND_NM);
};
scwin.fn_GetParIssue = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = dts_Issue;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIssue = function(arrPar) {
    tbx_isue_contn.setValue(arrPar[0].ISUE);
    tbx_emph_invstg.setValue(arrPar[0].EMPH);
    tbx_napprov_rsn.setValue(arrPar[0].NAPPROV);
    tbx_isue_contn_search.setValue(arrPar[0].ISUE_SEARCH_TEXT);
    tbx_emph_invstg_search.setValue(arrPar[0].EMPH_SEARCH_TEXT);
    tbx_napprov_rsn_search.setValue(arrPar[0].NAPPROV_SEARCH_TEXT);
    $c.stf.CopyDataSet(arrPar[0].DTS_ISSUE, dts_Issue);
    //dts_Issue.ResetStatus();

};
scwin.fn_setIssue = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=KOSPI_DELIB_ISSUE_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.prelistingkospi.select.cmtdelib.issue" + "&{P}PARAM01=" + '' + "&{P}PARAM02=" + '';
    dts_Issue.DataID = encodeURI(url);
    dts_Issue.Reset();
};
scwin.fn_GetParDtl = function(arrPar) {
    arrPar[0] = scwin.clickIsurCd;
    arrPar[1] = scwin.clickBzProcsNo;
    arrPar[2] = scwin.clickComNm;
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_BILL_STRT_DD, edt_BILL_END_DD) && $c.stf.compareFromToDate2(edt_COMITE_STRT_DD, edt_COMITE_END_DD)) {
        scwin.fn_list_sync();
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(countrow, grd_List);
};
scwin.btn_Excel_onclick = function() {
    scwin.fn_ExcelDown();
};
scwin.btn_COMITE_SDate_onclick = function() {
    popUpCalendar2(edt_COMITE_STRT_DD);
};
scwin.btn_COMITE_EDate_onclick = function() {
    popUpCalendar2(edt_COMITE_END_DD);
};
scwin.btn_BILL_SDate_onclick = function() {
    popUpCalendar2(edt_BILL_STRT_DD);
};
scwin.btn_BILL_EDate_onclick = function() {
    popUpCalendar2(edt_BILL_END_DD);
};
scwin.gform_onload = function() {
    $c.stf.showObj(tbx_isue_contn_search, false);
    $c.stf.showObj(tbx_emph_invstg_search, false);
    $c.stf.showObj(tbx_napprov_rsn_search, false);
    scwin.fn_setCode();
    //	fn_initSearchDate(tbx_COMITE_STRT_DD, tbx_COMITE_END_DD);
    //	fn_initSearchDate(tbx_BILL_STRT_DD, tbx_BILL_END_DD);

    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_list_sync();
    scwin.fn_setIssue();
};
scwin.img_ind_onclick = function() {
    scwin.fn_GetPar = fn_GetParStdInd;
    scwin.fn_SetPar = fn_SetParStdInd;
    $c.lc.fn_PopFindStdIndCd();
};
scwin.btn_isue_contn_onclick = async function() {
    scwin.fn_GetPar = fn_GetParIssue;
    scwin.fn_SetPar = fn_SetParIssue;
    await $c.frame.CreateDialogFrame("DLG_ISSUE", "../lstmgt/ULDSTF60009.gfm", "이슈사항", 10, 10, 670, 900, "window");
};
scwin.img_emph_invstg_onclick = async function() {
    scwin.fn_GetPar = fn_GetParIssue;
    scwin.fn_SetPar = fn_SetParIssue;
    await $c.frame.CreateDialogFrame("DLG_ISSUE", "../lstmgt/ULDSTF60009.gfm", "이슈사항", 10, 10, 670, 900, "window");
};
scwin.img_napprov_onclick = async function() {
    scwin.fn_GetPar = fn_GetParIssue;
    scwin.fn_SetPar = fn_SetParIssue;
    await $c.frame.CreateDialogFrame("DLG_ISSUE", "../lstmgt/ULDSTF60009.gfm", "이슈사항", 10, 10, 670, 900, "window");
};
scwin.cmb_PeriodTp1_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp1, "VALUE", cmb_PeriodTp1.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_BILL_STRT_DD, edt_BILL_END_DD);
};
scwin.cmb_PeriodTp2_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp2, "VALUE", cmb_PeriodTp2.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_COMITE_STRT_DD, edt_COMITE_END_DD);
};
scwin.grd_List_OnDblClick = async function(row, colid) {
    if (colid != 'COMITE_RSLT_NM') {
        return;
    }
    if (row > 0) {
        //그리드에서 선택시
        scwin.fn_setBzProcsNo(row);
    }
    scwin.fn_GetPar = fn_GetParDtl;
    scwin.fn_SetPar = undefined;
    var comite_tp_cd = dts_List.getCellData(row, "COMITE_TP_CD");
    if (comite_tp_cd == '1') {
        await $c.frame.CreateDialogFrame("DLG_PRECOM_DTL", "../lstproc/ULDSTF05010_STK_ReadOnly.gfm", "위원회결과", 10, 10, 560 + 10, 480 + 20, "window");
    } else if (comite_tp_cd == '2') {
        await $c.frame.CreateDialogFrame("DLG_PRECOM_DTL", "../lstinvstg/ULDSTF07108.gfm", "위원회결과", 10, 10, 570 + 5, 750 + 35, "window");
    }
};
